def solve(board, click):
    r, c = click
    if board[r][c] == 'M':
        board[r][c] = 'X'
        return board
    m, n = len(board), len(board[0])
    def dfs(i, j):
        mines = 0
        for di in [-1,0,1]:
            for dj in [-1,0,1]:
                if di == 0 and dj == 0: continue
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < n and board[ni][nj] == 'M':
                    mines += 1
        if mines > 0:
            board[i][j] = str(mines)
        else:
            board[i][j] = 'B'
            for di in [-1,0,1]:
                for dj in [-1,0,1]:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < m and 0 <= nj < n and board[ni][nj] == 'E':
                        dfs(ni, nj)
    dfs(r, c)
    return board

